import math
def min_Jumps(x, y, c):
    if x < 0 or y < 0 or c < 0:
        return 0
    # Check if it is possible to reach the given point
    if x <= c or y <= c:
        return 0
    # Get the time it takes to reach the point from the origin
    t1 = math.sqrt((x**2 + y**2) / (c**2))
    # Get the maximum time you can stay at one point
    t2 = math.sqrt((x**2 + c**2) / (y**2))
    # Check if it is possible to reach the point
    if t1 >= t2:
        return math.ceil(t1)
    # If it is not possible to reach the point, return -1
    else:
        return -1

