def min_Jumps(start, end, distance):
  if start == end or end == 0:
    return 0
  if start > end:
    return float('inf')
  steps = float('inf')
  for jump in range(start + 1, min(start + distance, end + 1)):
    steps = min(steps, 1 + min_Jumps(jump, end, distance))
  return steps

