def sum_Of_Primes(n):
  sum_ = 0
  for num in range(1, n+1):
    is_prime = True
    for i in range(2, int(num/2) + 1):
      if num % i == 0:
        is_prime = False
        break
    if is_prime:
      sum_ += num
  return sum_

