    current_end = 0
    furthest_reached = 0
    while furthest_reached < len(array) - 1:
        # Find the furthest reachable index from the current position
        furthest_reached = max(furthest_reached, array[current_end] + current_end)
        # Increment the number of jumps made
        jumps += 1
        # Update the current_end position to the furthest reachable index
        current_end = furthest_reached
    # Return the number of jumps required to reach the end
    return jumps
