  if m != n:
    return "Not Possible"
  if binary_str1 == binary_str2:
    return 0
  d = np.zeros((2,2)) # create a 2 x 2 matrix
  d[0][0] = 0; d[0][1] = 1; d[1][0] = 1; d[1][1] = 0
  for i in range(m):
