def count_Fac(n): 
      
    # Create a dict to store     # counts of prime factors 
    fact = {} 
    temp = n 
      
    # Check for each prime 
    # factor     while (temp % 2 == 0): 
        if 2 in fact: 
            fact[2] += 1
        else: 
            fact[2] = 1
        temp //= 2
      
    for i in range(3, int(n**0.5)+ 1, 2): 
      
        # Check if i is a factor of 
        # n. If true, then count 
        # of factors of n are incremented 
        while (temp % i == 0): 
            if i in fact: 
                fact[i] += 1
            else: 
                fact[i] = 1
            temp //= i 
      
    # Check if temp is a prime number 
    # which is greater than 2 
    if temp > 2: 
        fact[temp] = 1
      
    # Count of distinct prime     # factors 
    return len(fact)

