import heapq as hq
def max_average_of_path(matrix,n):
  hq.heapify(matrix)
  total_sum = 0
  max_avg = 0
  for i in range(n):
    total_sum += hq.heappop(matrix)
    if max_avg == 0:
      max_avg = hq.heappop(matrix)
    else:
      max_avg = max(max_avg, total_sum / (i + 1))
  return max_avg

