def pack_consecutive_duplicates(l):
    if len(l) == 0:
        return []
    result = []
    current = l[0]
    count = 1
    for i in range(1, len(l)):
        if l[i] == current:
            count += 1
        else:
            result.append([current, count])
            current = l[i]
            count = 1
    result.append([current, count])
    return result

