def prime_check(num):
  def sum_of_divisors(num):
    sum_div = 1
    for i in range(2, (num//2)+1):
      if num % i == 0:
        sum_div += i
    return sum_div
  if sum_of_divisors(num) == 2 * num and num > 1:
    return True
  else:
    return False
