def binomial_coefficient(n,i):
    if i>n:
        return 0
    else:
        return 1 if i==0 or i==n else binomial_coefficient(n-1,i-1)+binomial_coefficient(n-1,i)

def sum_of_square(n):
    sum = 0
    for i in range(n+1):
        sum += binomial_coefficient(n,i)**2
    return sum

