def find_closet(arr1,arr2,arr3,n,m,k):
  if n==0:
    return hq.nsmallest(k, arr2[:k]+arr3[:k])
  if m==0:
    return hq.nsmallest(k, arr1[:k]+arr3[:k])
  if k==0:
    return hq.nsmallest(n+m,arr1[:n]+arr2[:m])
  min_val = hq.nsmallest(k, arr1[:n]+arr2[:m]+arr3[:k])
  min_index = hq.heapify(min_val)
  while len(min_index) < k:
    if arr1[n-1] < arr2[m-1] and arr1[n-1] < arr3[k-1]:
      hq.heappushpop(min_index, arr1[n-1])
      n -= 1
    elif arr2[m-1] < arr1[n-1] and arr2[m-1] < arr3[k-1]:
      hq.heappushpop(min_index, arr2[m-1])
      m -= 1
    else:
      hq.heappushpop(min_index, arr3[k-1])
      k -= 1
  return min_index
