from math import factorial
def nCr_mod_p(n,r,p):
  if r>n:
    return 0
  num=factorial(n)
  den=factorial(r)*factorial(n-r)
  return (num*(pow(2,modInverse(den,p)-1,p))%p)
def modInverse(a, m):
  if 0 == a:
    return a
  b, b_ = a, m
  x, x_ = 0, 1
  while b != 0:
    q = b_ // a
    b, a = a, b % a
    x, x_ = x_ - q * x, x
  return x_ % m

def nCr_mod_p(n, r, p): 
    if (r > n): 
        return 0
    if (r == 0 or r == n): 
        return 1
    N = [0] * (n+1)
    N[0], N[1] = 1, 1 
    for i in range(2, n+1): 
        N[i] = (N[i - 1] * i) % p 
    C = [0] * (r+1) 
    C[0] = 1
    for i in range(1, r+1): 
        C[i] = (C[i - 1] * (n+1 - i)) % p 
    C[r] = (C[r] * N[n]) % p 
    return C[r]

def nCr_mod_p(n, r, p):
  res = 1
  for i in range(r):
    res = (res * (n - i)) % p
    res = (res * pow(i + 1, p - 2, p)) % p
  return res

